struct Barrier { std::mutex m; std::condition_variable cv; unsigned n,arrived=0,g=0; explicit Barrier(unsigned x):n(x){} void wait(){std::unique_lock<std::mutex> l(m);auto q=g;if(++arrived==n){arrived=0;++g;cv.notify_all();}else cv.wait(l,[&]{return g!=q;});} };
std::mutex log_mutex;
std::string read_bytes(const std::string&path){std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("no se puede leer "+path);return {std::istreambuf_iterator<char>(f),{}};}
std::string sha256_hex(const std::string&data){BCRYPT_ALG_HANDLE a=nullptr;BCRYPT_HASH_HANDLE h=nullptr;DWORD objn=0,got=0;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)throw std::runtime_error("SHA256 provider");if(BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&objn,sizeof(objn),&got,0)<0){BCryptCloseAlgorithmProvider(a,0);throw std::runtime_error("SHA256 object length");}std::vector<UCHAR>obj(objn),digest(32);if(BCryptCreateHash(a,&h,obj.data(),objn,nullptr,0,0)<0||BCryptHashData(h,(PUCHAR)data.data(),DWORD(data.size()),0)<0||BCryptFinishHash(h,digest.data(),DWORD(digest.size()),0)<0){if(h)BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);throw std::runtime_error("SHA256 digest");}BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);std::ostringstream o;o<<std::hex<<std::setfill('0');for(auto c:digest)o<<std::setw(2)<<unsigned(c);return o.str();}
bool is_sha256(const std::string&s){return s.size()==64&&std::all_of(s.begin(),s.end(),[](unsigned char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f');});}
std::string executable_path(){char b[MAX_PATH]{};DWORD n=GetModuleFileNameA(nullptr,b,MAX_PATH);if(!n||n>=MAX_PATH)throw std::runtime_error("GetModuleFileName failed");return std::string(b,n);}
std::string parent_path(const std::string&p){auto q=p.find_last_of("/\\");return q==std::string::npos?std::string("."):p.substr(0,q);}
void invoke_python_main(const std::string&script,const std::vector<std::string>&args){std::string command="python -B \""+script+"\"";for(const auto&arg:args)command+=" \""+arg+"\"";std::vector<char>writable(command.begin(),command.end());writable.push_back('\0');STARTUPINFOA si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};if(!CreateProcessA(nullptr,writable.data(),nullptr,nullptr,TRUE,0,nullptr,nullptr,&si,&pi))throw std::runtime_error("CreateProcess python failed error="+std::to_string(GetLastError()));WaitForSingleObject(pi.hProcess,INFINITE);DWORD code=1;GetExitCodeProcess(pi.hProcess,&code);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);if(code)throw std::runtime_error("python adapter exit="+std::to_string(code)+" command="+command);}
