void validate_a6(const std::string&auth,const std::string&plan_path,const std::string&expected_plan_sha){using namespace harness::strict_r11;auto j=Parser(auth).parse();const std::set<std::string> top={"schema","campaign","session_id","issued_at_utc","judge","sol_decision_id","scope","master_seed","plan_sha256","artifacts","usage_policy"};if(j.k!=J::Obj||j.o.size()!=top.size())throw std::runtime_error("S-18 A6 propiedades incorrectas");for(const auto&k:top)if(!j.o.count(k))throw std::runtime_error("S-18 A6 campo ausente: "+k);if(field_string(j,"schema")!="T0P_S18_A6_AUTHORIZED_V1")throw std::runtime_error("schema S-18 A6 no reconocido");for(auto k:{"campaign","session_id","judge","sol_decision_id","scope"})(void)field_string(j,k);std::regex utc("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$");if(!std::regex_match(field_string(j,"issued_at_utc"),utc))throw std::runtime_error("issued_at_utc no es UTC ISO-8601");if(field_string(j,"master_seed")!="4F4D454741543031")throw std::runtime_error("semilla maestra no coincide");auto p=Parser(read_bytes(plan_path)).parse();if(p.k!=J::Obj||p.o.size()!=4||field_string(p,"sha256")!=expected_plan_sha||field_string(j,"plan_sha256")!=expected_plan_sha)throw std::runtime_error("SHA256 del plan no coincide");auto&a=j.o.at("artifacts");const std::set<std::string> ak={"executable_sha256","protocol_sha256","manifest_sha256"};if(a.k!=J::Obj||a.o.size()!=ak.size())throw std::runtime_error("artifacts A6 inválido");for(const auto&k:ak)if(!a.o.count(k)||a.o.at(k).k!=J::Str||!is_sha256(a.o.at(k).s))throw std::runtime_error("hash ausente/tipo inválido en artifacts: "+k);auto exe=executable_path(),dir=parent_path(exe);const std::string obj_marker="\\logs_r12\\obj_r12";if(dir.size()>=obj_marker.size()&&dir.substr(dir.size()-obj_marker.size())==obj_marker)dir=parent_path(parent_path(dir));auto actual_exe=sha256_hex(read_bytes(exe)),actual_spec=sha256_hex(read_bytes(dir+"\\HARNESS_SPEC_r12.md")),actual_manifest=sha256_hex(read_bytes(dir+"\\SHA256SUMS_harness_r12.txt"));if(a.o.at("executable_sha256").s!=actual_exe)throw std::runtime_error("hash ejecutable no coincide");if(a.o.at("protocol_sha256").s!=actual_spec)throw std::runtime_error("hash protocolo no coincide");if(a.o.at("manifest_sha256").s!=actual_manifest)throw std::runtime_error("hash manifiesto no coincide");auto&u=j.o.at("usage_policy");if(u.k!=J::Obj||u.o.size()!=2||!u.o.count("session_count")||u.o.at("session_count").k!=J::Num||u.o.at("session_count").s!="1"||!u.o.count("technical_retry")||u.o.at("technical_retry").k!=J::Str||u.o.at("technical_retry").s!="one_global_technical_retry_same_plan_seed_order")throw std::runtime_error("política de sesión/reintento A6 inválida");}
uint64_t tsc(){_mm_lfence();unsigned aux=0;auto x=__rdtscp(&aux);_mm_lfence();return x;}
double qpc_seconds(int64_t a,int64_t b,int64_t f){return double(b-a)/double(f);}
double quantile(std::vector<double> v,double q){std::sort(v.begin(),v.end());double x=(v.size()-1)*q;auto i=(size_t)x;return v[i]+(x-i)*(v[std::min(i+1,v.size()-1)]-v[i]);}
bool page_query(const Region&r){if(!r.data||!r.bytes||!r.large)return false;auto p=(uintptr_t)r.data;auto n=r.bytes;SYSTEM_INFO si{};GetSystemInfo(&si);auto first=p&~(uintptr_t(si.dwPageSize)-1),last=(p+n-1)&~(uintptr_t(si.dwPageSize)-1);std::vector<PSAPI_WORKING_SET_EX_INFORMATION> q;for(auto a=first;;a+=si.dwPageSize){PSAPI_WORKING_SET_EX_INFORMATION z{};z.VirtualAddress=(void*)a;q.push_back(z);if(a==last)break;}if(!QueryWorkingSetEx(GetCurrentProcess(),q.data(),DWORD(q.size()*sizeof(q[0]))))return false;for(auto&z:q)if(!z.VirtualAttributes.Valid||!z.VirtualAttributes.LargePage)return false;return true;}
bool official_duration_gate(double seconds){return std::isfinite(seconds)&&seconds>=2.0;}
bool affinity_matches(KAFFINITY expected,KAFFINITY observed){return expected==observed;}
void margin(Provider&p,unsigned w,int m,const std::string&frontier,int64_t freq){LARGE_INTEGER a{},b{};QueryPerformanceCounter(&a);do{p.run_once_frontier(w,m,frontier);QueryPerformanceCounter(&b);}while(qpc_seconds(a.QuadPart,b.QuadPart,freq)<.200);}
struct Result{std::string name;double tsc_us=0,qpc_us=0;uint64_t start=0,end=0;bool affinity=false,valid=false;};
void emit(std::ofstream&f,const std::string&line){f<<line<<"\n";f.flush();}
struct Entry{std::string name;std::string plan_event;size_t plan_index=0;std::unique_ptr<Provider>(*factory)();std::vector<std::string>plan_events=std::vector<std::string>(31);std::vector<size_t>plan_indices=std::vector<size_t>(31,SIZE_MAX);};
bool is_torch(const std::string&name){return name.rfind("torch_",0)==0;}
CellSpec route_cell(CellSpec cell,const Entry&e){if(is_torch(e.name))cell.variant=e.name.substr(6);return cell;}
std::vector<Entry> planned_entries(const std::string&path,const std::string&expected_hash,size_t&event_count,const std::string&phase,const std::string&core,int m,const std::string&frontier){
  std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("PLAN_READ_FAIL "+path);std::string bytes((std::istreambuf_iterator<char>(f)),{});
  const std::string marker=",\"sha256\":\""+expected_hash+"\"";const auto hash_pos=bytes.rfind(marker);if(!is_sha256(expected_hash)||hash_pos==std::string::npos||hash_pos+marker.size()!=bytes.size()-1||bytes.back()!='}')throw std::runtime_error("PLAN_HASH_NOT_VERIFIED_BEFORE_CALIBRATION");const std::string canonical=bytes.substr(0,hash_pos)+"}";if(sha256_hex(canonical)!=expected_hash)throw std::runtime_error("PLAN_HASH_MISMATCH_BEFORE_CALIBRATION");
  std::regex idrx("\\\"id\\\":\\\"([^\\\"]+)\\\"");std::sregex_iterator it(bytes.begin(),bytes.end(),idrx),end;event_count=0;
  std::vector<Entry> base;
  if(phase=="competency")base={{"omega",{},0,make_omega},{"ggml_flat",{},0,make_ggml_flat},{"ggml_repack",{},0,make_ggml_repack},{"torch_mm",{},0,make_torch_out},{"torch_matmul",{},0,make_torch_out},{"torch_linear",{},0,make_torch_out}};
  else if(phase=="reference_selection_ggml")base={{"ggml_flat",{},0,make_ggml_flat},{"ggml_repack",{},0,make_ggml_repack}};
  else if(phase=="reference_selection_torch")base={{"torch_mm",{},0,make_torch_out},{"torch_matmul",{},0,make_torch_out},{"torch_linear",{},0,make_torch_out}};
  else throw std::runtime_error("PLAN_PHASE_UNSUPPORTED "+phase);
  if(m==1&&phase!="reference_selection_ggml")base.push_back({"torch_mv",{},0,make_torch_out});
  std::vector<size_t> first(base.size(),SIZE_MAX);std::vector<std::string> matched(base.size());
  size_t plan_position=0;for(;it!=end;++it){const std::string id=(*it)[1].str();const size_t ix=plan_position++;std::vector<std::string> fields;std::stringstream ss(id);std::string part;while(std::getline(ss,part,'|'))fields.push_back(part);if(fields.size()!=6||fields[0]!=phase||fields[1]!=core||fields[2]!="m"+std::to_string(m)||fields[3]!=frontier)continue;const auto replica=std::stoi(fields[4].substr(1));if(replica<1||replica>31)throw std::runtime_error("PLAN_REPLICA_OUT_OF_RANGE "+id);for(size_t j=0;j<base.size();++j)if(fields[5]==base[j].name){++event_count;const size_t ri=size_t(replica-1);if(base[j].plan_indices[ri]!=SIZE_MAX)throw std::runtime_error("PLAN_DUPLICATE_PROVIDER_REPLICA "+id);base[j].plan_events[ri]=id;base[j].plan_indices[ri]=ix;if(first[j]==SIZE_MAX){first[j]=ix;matched[j]=id;}}}
  std::vector<Entry> out;for(size_t j=0;j<base.size();++j){if(first[j]==SIZE_MAX)continue;for(size_t r=0;r<31;++r)if(base[j].plan_indices[r]==SIZE_MAX)throw std::runtime_error("PLAN_REPLICA_MISSING "+phase+"|"+core+"|m"+std::to_string(m)+"|"+frontier+"|"+base[j].name+"|r"+std::to_string(r+1));base[j].plan_event=matched[j];base[j].plan_index=first[j];out.push_back(base[j]);}
  std::sort(out.begin(),out.end(),[](const Entry&a,const Entry&b){return a.plan_index<b.plan_index;});if(out.empty())throw std::runtime_error("PLAN_HAS_NO_EVENTS_FOR "+phase+"|"+core+"|m"+std::to_string(m)+"|"+frontier);return out;
}
uint64_t calibrate_common_R(const CellSpec&cell,int64_t qpf,const std::string&outdir,const std::vector<Entry>&entries,const std::string&plan_sha,const std::string&phase,const std::string&core,const std::vector<unsigned>&active_workers){
  constexpr double target_s=2.5,pilot_s=.200;
  std::vector<std::vector<double>> rates(8,std::vector<double>(entries.size(),0.0));
  std::atomic<bool> setup{true};std::vector<std::thread> threads;Barrier stage(static_cast<unsigned>(active_workers.size()));
  for(unsigned w:active_workers)threads.emplace_back([&,w]{
    try{if(!set_worker_affinity_r12(w)||!worker_affinity_matches_r12(w))throw std::runtime_error("GetLogicalProcessorInformationEx affinity mismatch");}catch(const std::exception&x){setup=false;std::lock_guard<std::mutex> l(log_mutex);std::cerr<<"CALIBRATION worker="<<w<<" setup="<<x.what()<<"\n";}
    for(size_t pi=0;pi<entries.size();++pi){std::unique_ptr<Provider> p;try{if(setup){p=entries[pi].factory();p->prepare(route_cell(cell,entries[pi]),w);std::string why;if(!p->validate(why))throw std::runtime_error(entries[pi].name+" calibration "+why);for(auto&r:p->bytes_regions())if(!page_query(r))throw std::runtime_error(std::string("PAGE_FAIL calibration ")+r.name);}}catch(const std::exception&x){setup=false;std::lock_guard<std::mutex> l(log_mutex);std::cerr<<"CALIBRATION worker="<<w<<" provider="<<entries[pi].name<<" setup="<<x.what()<<"\n";}
      stage.wait();if(setup&&p){for(int k=0;k<5;++k)p->run_once_frontier(w,cell.m,cell.frontier);LARGE_INTEGER a{},b{};QueryPerformanceCounter(&a);uint64_t count=0;do{p->run_once_frontier(w,cell.m,cell.frontier);++count;QueryPerformanceCounter(&b);}while(qpc_seconds(a.QuadPart,b.QuadPart,qpf)<pilot_s);double elapsed=qpc_seconds(a.QuadPart,b.QuadPart,qpf);if(elapsed<=0)setup=false;else rates[w][pi]=double(count)/elapsed;}stage.wait();p.reset();
    }
  });
  for(auto&t:threads)t.join();if(!setup)throw std::runtime_error("common-R calibration setup failed");
  double fastest=0;for(unsigned w:active_workers)for(double r:rates[w])if(r>0){if(!std::isfinite(r))throw std::runtime_error("invalid calibration rate");fastest=std::max(fastest,r);}if(fastest<=0)throw std::runtime_error("invalid calibration rate");
  uint64_t common_R=uint64_t(std::ceil(fastest*target_s));if(!common_R)throw std::runtime_error("common R is zero");
  const std::string calibration_name="calibration_"+phase+"_"+core+"_"+cell.id+"_"+cell.frontier+".json";std::ofstream f(outdir+"\\"+calibration_name,std::ios::trunc);if(!f)throw std::runtime_error("cannot write "+calibration_name);
  f<<"{\"phase\":\""<<phase<<"\",\"core\":\""<<core<<"\",\"unit\":\""<<cell.id<<"\",\"frontier\":\""<<cell.frontier<<"\",\"plan_sha256\":\""<<plan_sha<<"\",\"target_s\":"<<target_s<<",\"minimum_s\":2.0,\"R_common\":"<<common_R<<",\"dispatch_order\":[";
  for(size_t pi=0;pi<entries.size();++pi){if(pi)f<<",";f<<"{\"provider\":\""<<entries[pi].name<<"\",\"first_plan_event\":\""<<entries[pi].plan_event<<"\",\"first_plan_index\":"<<entries[pi].plan_index<<"}";}f<<"],\"provider_workers\":[";
  bool first=true;for(size_t pi=0;pi<entries.size();++pi)for(unsigned w:active_workers){if(!first)f<<",";first=false;f<<"{\"provider\":\""<<entries[pi].name<<"\",\"worker\":"<<w<<",\"iterations_per_s\":"<<std::fixed<<std::setprecision(6)<<rates[w][pi]<<"}";}
  f<<"]}\n";f.flush();if(!f)throw std::runtime_error("cannot flush calibration.json");
  std::cout<<"CALIBRATION phase="<<phase<<" core="<<core<<" unit="<<cell.id<<" providers="<<entries.size()<<" active_workers="<<active_workers.size()<<" R_common="<<common_R<<" target_s="<<target_s<<" minimum_s=2.0 fastest_iter_s="<<fastest<<" plan_sha256="<<plan_sha<<"\n";
  return common_R;
}
